"""
Автопилот повторов: Atlas сам замечает, с чего ты начинаешь день, и предлагает делать это одной фразой.

  • По памяти компьютера: если утром (днём, вечером) хотя бы 3 разных дня ты открываешь одно и то же —
    например, эссе в Word, Spotify и Classroom, — Atlas один раз предлагает: «Сделать из этого
    рабочее место «утро»? Скажи «да, сделай»».
  • «Да, сделай» — и потом «режим утро» открывает всё сразу. «Не надо» — больше не предложит.
  • «Какие у меня привычки?» — что Atlas заметил.
  • Предложение — не чаще раза в день и не в первые 10 минут после запуска. AUTOPILOT=off — выключить.
  • Память компьютера теперь запоминает и путь к программе — чтобы автопилот мог её запустить.

    python apply_autopilot.py
    python apply_autopilot.py --rollback
"""
import base64
import hashlib
import os
import re
import shutil
import subprocess
import sys
import time

for _stream in (sys.stdout, sys.stderr):
    try:
        _stream.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass

ROOT = os.path.dirname(os.path.abspath(__file__))
ORIG = {'cloud/atlas_cloud.py': 'df7917740d16c2b4f63ab77cdde8e862f2a783241d771515ec8c9ec35466efbb', 'core/worklog.py': '5d8ba171b3ec7c316d03974e7b697a42f4d1cd65bd2e57f6b3fd7558984d6cfc', 'main.py': '65b263ebdc828138a632335fa7c1d57eb222ca012a514b681a65b20e26de109e', 'skills/worklog.py': '4e17ef0b111bd6f658947af617cda78e6fd0162c7c6666b7d52b5ea4e4e58df4', 'tests/test_worklog.py': '8877aadd80a9fc42faf2cee4eed7509ddf82474c8e868f86e4c9817fbb500450', 'core/autopilot.py': None}
NEW = {'cloud/atlas_cloud.py': '', 'core/worklog.py': '', 'main.py': '', 'skills/worklog.py': '', 'tests/test_worklog.py': '', 'core/autopilot.py': ''}
TAG = "backup_autopilot_"


def p(rel):
    return os.path.join(ROOT, *rel.split("/"))


def restore(backup):
    for rel, h in ORIG.items():
        if h is None:
            if os.path.exists(p(rel)):
                os.remove(p(rel))
        else:
            shutil.copy2(os.path.join(backup, *rel.split("/")), p(rel))
    print(f"Вернул прежние файлы из {backup}.")


if "--rollback" in sys.argv:
    cands = sorted(d for d in os.listdir(ROOT) if d.startswith(TAG))
    if not cands:
        sys.exit("Резервной копии нет.")
    restore(p(cands[-1]))
    sys.exit(0)
if os.path.exists(p('core/autopilot.py')) and 'def find_habits' in open(p('core/autopilot.py'), encoding="utf-8").read():
    sys.exit("Уже установлено.")

differ = []
for rel, h in ORIG.items():
    if h is None:
        if os.path.exists(p(rel)):
            differ.append(f"{rel} — уже есть такой файл")
        continue
    if not os.path.exists(p(rel)):
        differ.append(f"{rel} — нет файла")
        continue
    got = hashlib.sha256(open(p(rel), "rb").read().replace(b"\r\n", b"\n")).hexdigest()
    if got != h:
        differ.append(rel)
if differ:
    print("  ! отличаются от версии на GitHub: " + ", ".join(differ))
    sys.exit("Эти файлы у тебя изменены — ничего не тронул. Сделай git pull (или пришли мне вывод), потом запусти снова.")

backup = p(time.strftime(TAG + "%Y%m%d_%H%M%S"))
for rel, h in ORIG.items():
    if h is not None:
        os.makedirs(os.path.dirname(os.path.join(backup, *rel.split("/"))), exist_ok=True)
        shutil.copy2(p(rel), os.path.join(backup, *rel.split("/")))
print(f"Резервная копия: {backup}")
for rel, data in NEW.items():
    os.makedirs(os.path.dirname(p(rel)) or ROOT, exist_ok=True)
    with open(p(rel), "wb") as f:
        f.write(base64.b64decode(data))
print("  ✓ автопилот повторов: замечает, что ты открываешь каждый день, и предлагает рабочее место")

env = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUTF8="1")
suites = [f for f in sorted(os.listdir(p("tests"))) if f.startswith("test_") and f.endswith(".py")]
for suite in suites:
    try:
        r = subprocess.run([sys.executable, p("tests/" + suite)], cwd=ROOT, capture_output=True, text=True,
                           encoding="utf-8", errors="replace", timeout=300, env=env)
        out, code = r.stdout + r.stderr, r.returncode
    except subprocess.TimeoutExpired:
        out, code = "✗ тесты не закончились за 5 минут", 1
    m = re.search(r"Тестов пройдено: (\d+) из (\d+)", out)
    good = code == 0 and m and m.group(1) == m.group(2)
    print(f"  {'✓' if good else '✗'} tests/{suite}: {m.group(0) if m else 'итоговой строки нет'}")
    if not good:
        lines = out.splitlines()
        for i, ln in enumerate(lines):
            if ln.strip().startswith("✗"):
                print("      " + "\n      ".join(x.rstrip() for x in lines[i:i + 7]))
        restore(backup)
        sys.exit("✗ Проверка не прошла — всё возвращено.")
print("\nГотово. Дальше: git add -A, git commit, git push; перезапусти Atlas.")
print("Привычке нужно минимум 3 дня памяти компьютера — первые предложения появятся через несколько дней.")

